sys_script_include.script:
var NurseUtilsClient = Class.create();
NurseUtilsClient.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getNurseDetails: function () {
        var nurse = new GlideRecord('u_nurse');
        if (nurse.get(this.getParameter('sysparm_nurse_id'))) {
            return JSON.stringify({
                first_name: nurse.getValue('u_first_name'),
                department: nurse.getValue('u_department')
            });
        }
        return JSON.stringify({error: "Nurse not found"});
    }
});
